public double[] fit(int maxEval, final ParametricUnivariateRealFunction f,
                    final double[] initialGuess) {
    // prepare least squares problem
    double[] target  = new double[observations.size()];
    double[] weights = new double[observations.size()];
    int i = 0;
    for (WeightedObservedPoint point : observations) {
        target[i]  = point.getY();
        weights[i] = point.getWeight();
        ++i;
    }

    // perform the fit
    VectorialPointValuePair optimum =
        optimizer.optimize(maxEval, new TheoreticalValuesFunction(f),
                           target, weights, initialGuess);

    // extract the coefficients
    return optimum.getPointRef();
}

public double[] fit(double[] initialGuess) {
    final ParametricUnivariateRealFunction f = new ParametricUnivariateRealFunction() {
            private final ParametricUnivariateRealFunction g = new Gaussian.Parametric();

            public double value(double x, double[] p) {
                double v = Double.POSITIVE_INFINITY;
                try {
                    v = g.value(x, p);
                } catch (NotStrictlyPositiveException e) {
                    // Do nothing.
                }
                return v;
            }

            public double[] gradient(double x, double[] p) {
                double[] v = { Double.POSITIVE_INFINITY,
                               Double.POSITIVE_INFINITY,
                               Double.POSITIVE_INFINITY };
                try {
                    v = g.gradient(x, p);
                } catch (NotStrictlyPositiveException e) {
                    // Do nothing.
                }
                return v;
            }
        };

    return fit(f, initialGuess);
}

